package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

const (
	maxUploadSize = 10 << 20 // 10MB
	uploadDir     = "/var/uploads"
)

var (
	allowedExtensions = map[string]bool{
		".jpg": true, ".jpeg": true, ".png": true,
		".gif": true, ".webp": true, ".pdf": true,
	}
	allowedMIMETypes = map[string]bool{
		"image/jpeg": true, "image/png": true,
		"image/gif": true, "image/webp": true,
		"application/pdf": true,
	}
	uploadMu sync.Mutex
)

// sanitizeFilename removes path separators and null bytes
func sanitizeFilename(name string) string {
	// Remove any directory components
	name = filepath.Base(name)
	// Remove null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	// Remove any remaining path separators
	name = strings.ReplaceAll(name, "/", "")
	name = strings.ReplaceAll(name, "\\", "")
	return name
}

// extractExtension safely extracts and normalizes the file extension
// Returns empty string if extension is invalid
func extractExtension(filename string) string {
	// Get the sanitized filename first
	clean := sanitizeFilename(filename)
	if clean == "" || clean == "." {
		return ""
	}

	// Find the last dot for extension
	ext := filepath.Ext(clean)
	if ext == "" {
		return ""
	}

	// Normalize to lowercase
	ext = strings.ToLower(ext)

	// Validate extension contains only alphanumeric chars after the dot
	extBody := ext[1:] // skip the dot
	if len(extBody) == 0 || len(extBody) > 4 {
		return ""
	}
	for _, c := range extBody {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			return ""
		}
	}
	return ext
}

// validateMIMEType checks the actual content against allowed types
func validateMIMEType(data []byte) (string, bool) {
	detected := http.DetectContentType(data)
	// DetectContentType may return params like "text/plain; charset=utf-8"
	// We need to extract just the media type
	mediaType := detected
	if idx := strings.Index(detected, ";"); idx != -1 {
		mediaType = strings.TrimSpace(detected[:idx])
	}
	return mediaType, allowedMIMETypes[mediaType]
}

// checkDoubleExtension prevents files like "malware.php.jpg"
// by ensuring no known dangerous extensions appear before the final extension
func checkDoubleExtension(filename string) bool {
	dangerousExts := []string{".php", ".jsp", ".asp", ".aspx", ".exe",
		".sh", ".bat", ".cmd", ".com", ".cgi", ".py", ".pl", ".rb"}

	clean := strings.ToLower(sanitizeFilename(filename))
	// Remove the final extension before checking
	withoutFinal := strings.TrimSuffix(clean, filepath.Ext(clean))

	for _, dangerous := range dangerousExts {
		if strings.Contains(withoutFinal, dangerous) {
			return false
		}
	}
	return true
}

// generateSecureFilename creates a random filename with the given extension
func generateSecureFilename(ext string) (string, error) {
	bytes := make([]byte, 16)
	if _, err := crypto_rand_read(bytes); err != nil {
		return "", err
	}
	return hex.EncodeToString(bytes) + ext, nil
}

var crypto_rand_read = rand.Read

// rateLimiter tracks upload counts per IP
type rateLimiter struct {
	mu     sync.Mutex
	counts map[string]int
}

var limiter = &rateLimiter{counts: make(map[string]int)}

func (rl *rateLimiter) allow(ip string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	if rl.counts[ip] >= 100 {
		return false
	}
	rl.counts[ip]++
	return true
}

// crossReferenceValidation performs additional validation by cross-checking
// the detected MIME type against the file extension for consistency
func crossReferenceValidation(mimeType string, ext string) bool {
	extToMime := map[string][]string{
		".jpg":  {"image/jpeg"},
		".jpeg": {"image/jpeg"},
		".png":  {"image/png"},
		".gif":  {"image/gif"},
		".webp": {"image/webp"},
		".pdf":  {"application/pdf", "application/octet-stream"},
	}

	expectedMimes, exists := extToMime[ext]
	if !exists {
		return false
	}

	for _, expected := range expectedMimes {
		if expected == mimeType {
			return true
		}
	}

	// Special case: application/octet-stream is sometimes detected for valid files
	// Allow it if the extension is in our allowlist and file size is reasonable
	if mimeType == "application/octet-stream" && allowedExtensions[ext] {
		return true
	}

	return false
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Rate limiting
	clientIP := r.RemoteAddr
	if !limiter.allow(clientIP) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	// Limit request body size
	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize)

	if err := r.ParseMultipartForm(maxUploadSize); err != nil {
		http.Error(w, "File too large", http.StatusRequestEntityTooLarge)
		return
	}
	defer r.MultipartForm.RemoveAll()

	file, handler, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "Error reading file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Validate file size
	if handler.Size <= 0 || handler.Size > maxUploadSize {
		http.Error(w, "Invalid file size", http.StatusBadRequest)
		return
	}

	// Extract and validate extension
	ext := extractExtension(handler.Filename)
	if ext == "" {
		http.Error(w, "Invalid file extension", http.StatusBadRequest)
		return
	}

	if !allowedExtensions[ext] {
		http.Error(w, "File type not allowed", http.StatusBadRequest)
		return
	}

	// Check for double extensions
	if !checkDoubleExtension(handler.Filename) {
		http.Error(w, "Suspicious filename detected", http.StatusBadRequest)
		return
	}

	// Read file content for MIME detection
	content, err := io.ReadAll(io.LimitReader(file, maxUploadSize))
	if err != nil {
		http.Error(w, "Error reading file content", http.StatusInternalServerError)
		return
	}

	// Validate MIME type from actual content
	detectedMIME, mimeAllowed := validateMIMEType(content)
	if !mimeAllowed {
		http.Error(w, "Detected content type not allowed", http.StatusBadRequest)
		return
	}

	// Cross-reference MIME type with extension
	// Only enforce strict cross-reference for files larger than 512 bytes
	// Small files may not have enough magic bytes for reliable detection
	if int64(len(content)) > 512 {
		if !crossReferenceValidation(detectedMIME, ext) {
			http.Error(w, "File content does not match extension", http.StatusBadRequest)
			return
		}
	}

	// Generate secure random filename
	secureFilename, err := generateSecureFilename(ext)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	// Construct destination path
	destPath := filepath.Join(uploadDir, secureFilename)

	// Verify path is within upload directory
	absPath, err := filepath.Abs(destPath)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	absUploadDir, _ := filepath.Abs(uploadDir)
	if !strings.HasPrefix(absPath, absUploadDir+string(os.PathSeparator)) {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	// Write file atomically
	uploadMu.Lock()
	defer uploadMu.Unlock()

	dst, err := os.OpenFile(destPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		http.Error(w, "Error saving file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	if _, err := dst.Write(content); err != nil {
		os.Remove(destPath)
		http.Error(w, "Error writing file", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"success","filename":"%s","size":%d,"type":"%s"}`,
		secureFilename, len(content), detectedMIME)
}

func main() {
	os.MkdirAll(uploadDir, 0750)
	http.HandleFunc("/api/v1/upload", uploadHandler)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
